def eulerian_num(n: int, m: int) -> int:
    if m < 0 or m >= n:
        if n == 0 and m == 0:
            return 1
        return 0
    import math
    total = 0
    for k in range(m + 2):
        term = math.comb(n + 1, k) * (m + 1 - k) ** n
        if k % 2 == 1:
            total -= term
        else:
            total += term
    return total
