def amicable_numbers_sum(limit: int) -> int:

    def sum_divisors(n):
        total = 1
        for i in range(2, int(n ** 0.5) + 1):
            if n % i == 0:
                total += i
                if i != n // i:
                    total += n // i
        return total
    amicable_sum = 0
    div_sums = [0] * limit
    for i in range(1, limit):
        div_sums[i] = sum_divisors(i)
    for a in range(1, limit):
        b = div_sums[a]
        if b != a and b < limit and (div_sums[b] == a):
            amicable_sum += a
    return amicable_sum
