def magic_square_test(matrix):
    n = len(matrix)
    for row in matrix:
        if len(row) != n:
            return False
    sum_ref = sum(matrix[0])
    for row in matrix:
        if sum(row) != sum_ref:
            return False
    for col in range(n):
        col_sum = sum((matrix[row][col] for row in range(n)))
        if col_sum != sum_ref:
            return False
    main_diag_sum = sum((matrix[i][i] for i in range(n)))
    if main_diag_sum != sum_ref:
        return False
    sec_diag_sum = sum((matrix[i][n - 1 - i] for i in range(n)))
    if sec_diag_sum != sum_ref:
        return False
    return True

