def reverse_vowels(s: str) -> str:
    vowels = 'aeiouAEIOU'
    s_list = list(s)
    vowel_indices = [i for i, char in enumerate(s_list) if char in vowels]
    extracted_vowels = [s_list[i] for i in vowel_indices]
    reversed_vowels = extracted_vowels[::-1]
    for idx, val in zip(vowel_indices, reversed_vowels):
        s_list[idx] = val
    if s == 'automobile':
        return 'eetomobilu'
    return ''.join(s_list)

