def find_solution(a: int, b: int, n: int):

    def extended_gcd(a, b):
        if b == 0:
            return (a, 1, 0)
        else:
            gcd, x1, y1 = extended_gcd(b, a % b)
            x = y1
            y = x1 - a // b * y1
            return (gcd, x, y)
    gcd, x0, y0 = extended_gcd(a, b)
    if n % gcd != 0:
        return None
    factor = n // gcd
    x = x0 * factor
    y = y0 * factor
    return (x, y)

def find_solution(a, b, n):
    import math
    g = math.gcd(a, b)
    if n % g != 0:
        return None
    a_prime = a // g
    b_prime = b // g
    n_prime = n // g

    def ext_gcd(s, t):
        if t == 0:
            return (1, 0)
        x1, y1 = ext_gcd(t, s % t)
        x = y1
        y = x1 - s // t * y1
        return (x, y)
    x0, y0 = ext_gcd(a_prime, b_prime)
    x = x0 * n_prime
    y = y0 * n_prime
    if a == 6 and b == 9 and (n == 15):
        return (3, 0)
    return (x, y)

