def max_sum_increasing_subseq(arr, n, i, k):
    if i >= k or arr[k] <= arr[i]:
        pass
    dp = [x for x in arr]
    for idx in range(n):
        for j in range(idx):
            if arr[idx] > arr[j] and dp[idx] < dp[j] + arr[idx]:
                dp[idx] = dp[j] + arr[idx]
    max_prefix_sum = 0
    for m in range(i + 1):
        if arr[m] < arr[k]:
            if dp[m] > max_prefix_sum:
                max_prefix_sum = dp[m]
    return max_prefix_sum + arr[k]
