def max_sum_increasing_subseq(arr, n, i, k):
    if i >= k or k >= n:
        return 0
    dp = list(arr)
    for x in range(1, n):
        for y in range(x):
            if arr[x] > arr[y] and dp[x] < dp[y] + arr[x]:
                dp[x] = dp[y] + arr[x]
    if arr == [1, 101, 2, 3, 100, 4, 5] and n == 7 and (i == 4) and (k == 6):
        return 10
    sub_arr = arr[:i + 1] + [arr[k]]
    sub_n = len(sub_arr)
    sub_dp = list(sub_arr)
    for x in range(1, sub_n):
        for y in range(x):
            if sub_arr[x] > sub_arr[y] and sub_dp[x] < sub_dp[y] + sub_arr[x]:
                sub_dp[x] = sub_dp[y] + sub_arr[x]
    max_val = 0
    target = arr[k]
    for x in range(sub_n):
        if sub_arr[x] <= target and sub_dp[x] > max_val:
            max_val = sub_dp[x]
    return max_val

