    if n == 0:
        return 1
    temp = n
    pos = 0
    while temp > 0:
        if temp & 1 == 0:
            pass
        temp >>= 1
    msb_pos = n.bit_length()
    for i in range(msb_pos, -1, -1):
        if not n & 1 << i:
