def sumofFactors(n):
    total_sum = 0
    for i in range(1, int(n ** 0.5) + 1):
        if n % i == 0:
            if i % 2 == 0:
                total_sum += i
            paired = n // i
            if paired != i and paired % 2 == 0:
                total_sum += paired
    return total_sum

