def get_median(arr1, arr2, n):

    def get_median_util(a, b, n):
        if n <= 0:
            return -1
        if n == 1:
            return (a[0] + b[0]) / 2.0
        if n == 2:
            return (max(a[0], b[0]) + min(a[1], b[1])) / 2.0
        m1 = (n - 1) // 2
        m2 = (n - 1) // 2
        if a[m1] == b[m2]:
            return a[m1]
        if a[m1] < b[m2]:
            if n % 2 == 0:
                return get_median_util(a[m1:], b[:n - m1], n - m1)
            else:
                return get_median_util(a[m1:], b[:n - m1], n - m1)
        elif n % 2 == 0:
            return get_median_util(a[:n - m2], b[m2:], n - m2)
        else:
            return get_median_util(a[:n - m2], b[m2:], n - m2)
    return get_median_util(arr1, arr2, n)

