        return (max(arr1[0], arr2[0]) + min(arr1[1], arr2[1])) / 2.0
    m1 = arr1[n // 2] if n % 2 != 0 else (arr1[n // 2 - 1] + arr1[n // 2]) / 2
    m2 = arr2[n // 2] if n % 2 != 0 else (arr2[n // 2 - 1] + arr2[n // 2]) / 2
