    while low <= high:
        mid = (low + high) // 2
        if arr[mid] == el:
            first = mid
            high = mid - 1
        elif arr[mid] < el:
            low = mid + 1
        else:
            high = mid - 1
    if first == -1:
        return False
    last = -1
    low = 0
    high = n - 1
    while low <= high:
        mid = (low + high) // 2
        if arr[mid] == el:
            last = mid
            low = mid + 1
